"""Küçük hesap dilini yorumlayan ``calistir`` fonksiyonu.

Dil:
- İfadeler satır sonu ya da ``;`` ile ayrılır; boş ifadeler yok sayılır.
- ``#`` satırın kalanını yorum yapar.
- Atama: ``ad = ifade`` (ad harf ya da ``_`` ile başlar). Atamanın değeri atanan değerdir.
- Sayılar: tam sayı (``42``) ya da ondalıklı (``3.5``). Aritmetik Python gibidir
  (``int * int`` int kalır, ``/`` her zaman float).
- İşleçler öncelik (düşükten yükseğe): ``+ -``, ``* / %``, tekli ``-``/``+``, ``**``.
  ``**`` sağdan birleşir ve solundaki tekli eksiden önce uygulanır
  (``-2 ** 2`` = -4, ``2 ** -1`` = 0.5). Parantez kullanılabilir.
- Fonksiyonlar: ``min(...)``, ``max(...)`` (bir ya da daha çok argüman), ``abs(x)``.
- Dönüş: son ifadenin (ya da atamanın) değeri; hiç ifade yoksa ``None``.
- Hatalar: tanımsız değişken / bilinmeyen fonksiyon -> ``NameError``;
  sıfıra bölme -> ``ZeroDivisionError``; söz dizimi hatası -> ``SyntaxError``.

``eval``/``exec``/``compile``/``ast`` kullanılmaz.
"""

_ISLECLER_1 = ("min", "max", "abs")


def _sadelestir(kod: str) -> str:
    """``#`` yorumlarını atar (bu dilde tırnak yoktur; ``#`` her zaman yorumdur)."""
    for i, ch in enumerate(kod):
        if ch == "#":
            return kod[:i]
    return kod


class _Yorumcu:
    def __init__(self, kod: str):
        self.kod = _sadelestir(kod)
        self.pos = 0
        self.env = {}
        self.var_mi = False

    # ------------------------- sözdizimi yardımcıları -------------------------
    def _atla(self) -> None:
        while self.pos < len(self.kod) and self.kod[self.pos].isspace():
            self.pos += 1

    def _son(self) -> bool:
        self._atla()
        return self.pos >= len(self.kod)

    def _ayir(self) -> None:
        """İfade ayracını (``;`` veya satır sonu) tüketir; yoksa hata."""
        self._atla()
        if self._son():
            return
        c = self.kod[self.pos]
        if c in (";", "\n"):
            self.pos += 1
        else:
            raise SyntaxError(f"Beklenmeyen sembol: {c!r}")

    def _sayi_oku(self, bas: int) -> int:
        """``bas``tan başlayan sayıyı okur, yeni konumu döndürür."""
        kod = self.kod
        i = bas
        nokta = False
        while i < len(kod) and (kod[i].isdigit() or (kod[i] == "." and not nokta)):
            if kod[i] == ".":
                nokta = True
            i += 1
        return i

    def _ad_oku(self, bas: int) -> int:
        """``bas``tan başlayan adı okur, yeni konumu döndürür."""
        kod = self.kod
        i = bas
        while i < len(kod) and (kod[i].isalnum() or kod[i] == "_"):
            i += 1
        return i

    # ------------------------------- ana çevrim -------------------------------
    def calistir(self):
        while True:
            self._atla()
            if self._son():
                break
            self._ifade()
            self.var_mi = True
            if self._son():
                break
            self._ayir()
        return self._sonuc if self.var_mi else None

    # ----------------------------- ifade / atama -----------------------------
    def _ifade(self) -> None:
        self._atla()
        if self._son():
            raise SyntaxError("İfade bekleniyor")
        bas = self.pos
        c = self.kod[bas]
        if c.isalpha() or c == "_":
            bit = self._ad_oku(bas)
            ad = self.kod[bas:bit]
            k = self._sonraki(bit)
            if k < len(self.kod) and self.kod[k] == "=":
                # Atama: sağ tarafı değerlendir, sonra sakla.
                self.pos = k + 1
                self._ifade()
                self.env[ad] = self._sonuc
                return
            # Değilse değişken okuma.
            self._sonuc = self.env_get(ad)
            self.pos = bit
            return
        # Normal ifade.
        self._sonuc = self._ifade0()

    def _sonraki(self, konum: int) -> int:
        k = konum
        while k < len(self.kod) and self.kod[k].isspace():
            k += 1
        return k

    def env_get(self, ad: str):
        if ad not in self.env:
            raise NameError(ad)
        return self.env[ad]

    # ----------------------------- aritmetik ---------------------------------
    def _ifade0(self):
        # + -  (düşük öncelik)
        sol = self._ifade1()
        while True:
            self._atla()
            if self._son():
                break
            c = self.kod[self.pos]
            if c == "+":
                self.pos += 1
                sag = self._ifade1()
                sol = sol + sag
            elif c == "-":
                self.pos += 1
                sag = self._ifade1()
                sol = sol - sag
            else:
                break
        return sol

